const generatedImageChecksum = crypto.createHash('sha256').update(fs.readFileSync(generatedImagePath)).digest('hex')
const publicCopySignals = {
  webUsesGenerated: webIslandSource.includes('generatedIslandImage("san-salvador.png")') && webImageSource.includes('generatedIsland("san-salvador.png")'),
  generatedChecksumMatchesReviewedImage: generatedImageChecksum === '9b65f85a79e5e2d187c9b1bf99ff922226f94b30297ff39573d6ba4208fcf03a',
  mobileUsesLegacyHero: mobileImageSource.includes(urls.bmotLegacy),
  mobileWideAliasesSameImage: /sanSalvadorWide\s*=\s*sanSalvador/.test(mobileImageSource),
}
if (Object.values(publicCopySignals).some((value) => !value)) throw new Error('Public-copy signals changed: ' + JSON.stringify(publicCopySignals))

const env = loadEnv(path.join(workspaceRoot, 'bahabuddy-web/.env.local'))
const supabaseUrl = env.NEXT_PUBLIC_SUPABASE_URL
const supabaseKey = env.SUPABASE_SERVICE_ROLE_KEY || env.NEXT_PUBLIC_SUPABASE_ANON_KEY
