const supabaseRows = await supabaseResponse.json()
const supabaseById = new Map(supabaseRows.map((row) => [row.id, row]))

const candidateIds = [
  'drafts.canonical-place-candidate-san-salvador-bonefish-bay-beach',
  'drafts.canonical-place-candidate-san-salvador-gerace-research-centre',
]
const live = await client.fetch('{"sources": *[_id in $sourceIds]{...}, "publishedPlaces": *[_type == "placeEditorial" && !(_id in path("drafts.**")) && destination._ref == $destinationId]{...}, "placeDrafts": *[_type == "placeEditorial" && _id in path("drafts.**") && destination._ref == $destinationId]{...}, "candidates": *[_id in $candidateIds]{...}, "images": *[_id in $imageIds]{...}, "facts": *[_id in $factIds]{...}, "audit": *[_id == $auditId][0]{...}, "destinationPublished": *[_id == $destinationId][0]{...}, "destinationDraft": *[_id == $destinationDraftId][0]{...}, "publishedFacts": count(*[_type == "islandFact" && !(_id in path("drafts.**"))]), "sanSalvadorFactChannels": count(*[_type == "islandFact" && _id in path("drafts.**") && destination._ref == $destinationId && count(channels) > 0]), "publishedImageCandidates": count(*[_type == "imageCandidate" && !(_id in path("drafts.**"))])}', {sourceIds: Object.values(sourceIds), candidateIds, imageIds: Object.values(imageIds), factIds: Object.values(factIds), auditId, destinationId, destinationDraftId})
