for (const id of [sourceIds.island, sourceIds.watlings, sourceIds.bntIndex, sourceIds.bntGreatLake, sourceIds.gerace, sourceIds.mediaBoundary, sourceIds.publicMap, sourceIds.doaAirports, sourceIds.caabRegister, sourceIds.flightTables, sourceIds.hotelDirectory]) if (!sourceById.has(id)) throw new Error('Missing source: ' + id)
