if (live.publishedPlaces.length !== 41) throw new Error('Expected 41 published San Salvador overlays, found ' + live.publishedPlaces.length)
if (live.candidates.length !== 2) throw new Error('Expected two San Salvador signature candidates, found ' + live.candidates.length)
